package chihalu.customstacklimit.mixin;

import net.minecraft.item.Item;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.Constant;
import org.spongepowered.asm.mixin.injection.ModifyConstant;

/**
 * Item.SettingsのmaxCount定数(99)を変更
 */
@Mixin(Item.Settings.class)
public class ItemSettingsMixin {

    /**
     * maxCount()メソッド内の定数99を32767に変更
     * これにより99個の制限を解除
     */
    @ModifyConstant(method = "maxCount", constant = @Constant(intValue = 99))
    private int modifyMaxCountLimit(int original) {
        return 32767; // 最大値を32767に変更
    }
}
